ALTER TABLE `hilos_notification_delivery` ADD COLUMN `__hil1923_created_at` BIGINT NULL, ADD COLUMN `__hil1923_updated_at` BIGINT NULL, ADD COLUMN `__hil1923_delivered_at` BIGINT NULL;
