ALTER TABLE `hilos_notification_delivery` DROP INDEX `idx_notification_delivery_created`, DROP INDEX `idx_notification_delivery_status_created`, DROP COLUMN `created_at`, DROP COLUMN `updated_at`, DROP COLUMN `delivered_at`, CHANGE COLUMN `__hil1923_created_at` `created_at` BIGINT NOT NULL, CHANGE COLUMN `__hil1923_updated_at` `updated_at` BIGINT NOT NULL, CHANGE COLUMN `__hil1923_delivered_at` `delivered_at` BIGINT NULL DEFAULT NULL, ADD INDEX `idx_notification_delivery_created` (`created_at`), ADD INDEX `idx_notification_delivery_status_created` (`status`, `created_at`);
